from gen import *
def sw(name,hexv,tok,fg='#fff'):
    return f'<div><div style="height:64px;border-radius:8px;background:{hexv};border:1px solid #0001;display:flex;align-items:flex-end;padding:6px 8px;color:{fg};font-size:11px;font-weight:600">{hexv}</div><div class="small" style="margin-top:6px;font-weight:600">{name}</div><div class="xs muted">{tok}</div></div>'
pal=''.join([sw('Papel','#F6F3EC','--bg','#1F1B16'),sw('Superfície','#FFFDF8','--surface/card','#1F1B16'),sw('Muted','#EEE9DE','--muted','#1F1B16'),sw('Borda','#DDD5C4','--border','#1F1B16'),sw('Tinta','#1F1B16','--foreground'),sw('Tinta 2','#5C5448','--muted-foreground'),sw('Bordô','#6E1E2B','--primary'),sw('Latão','#A9823A','--accent / --ring')])
sem=''.join([sw('Ao vivo','#B42318','--status-live'),sw('Agendado','#2F5D8A','--status-scheduled'),sw('Encerrado','#5C5448','--status-closed'),sw('Sucesso/íntegro','#1E6B45','--success'),sw('Aviso/simulado','#8A5300','--warning'),sw('Erro/adulterado','#B42318','--destructive')])
alt=''.join([sw('Papel frio','#F4F5F2','--bg','#1F1B16'),sw('Tinta','#1A1F1D','--foreground'),sw('Verde-museu','#1F4D45','--primary'),sw('Cobre','#B5653A','--accent'),sw('Superfície','#FFFFFF','--card','#1F1B16')])
def prop(logo,name,why,rec=False):
    return f'''<div class="card" style="padding:20px;{'outline:2px solid var(--accent);' if rec else ''}"><div class="row" style="justify-content:space-between"><div class="row">{logo}<span class="serif" style="font-size:26px;font-weight:600">{name}</span></div>{'<span class="badge b-ext">Recomendado</span>' if rec else '<span class="badge b-closed">Alternativa</span>'}</div><p class="small muted" style="margin-top:12px">{why}</p></div>'''
icons=['gavel','wallet','timer','clock','history','shield-check','shield-alert','shield-question','trophy','receipt','search','image-off','wifi-off','refresh-cw','circle-check','circle-alert','triangle-alert','info','lock','log-in','log-out','user','link','copy','printer','eye','chevron-right','menu','x','loader-circle','trending-up','calendar','hourglass','plus','arrow-up-right']
ig=''.join(f'<div style="text-align:center;padding:10px 4px;background:var(--surface);border:1px solid var(--border);border-radius:8px">{ic(i,22)}<div class="xs muted" style="margin-top:4px">{i}</div></div>' for i in icons)
ty=[('Display / H1','Fraunces 600 · 40/44 · -1%','<span class="serif" style="font-size:40px;font-weight:600">Campo de trigo</span>'),
('H2','Fraunces 600 · 28/34','<span class="serif" style="font-size:28px;font-weight:600">Lotes ao vivo</span>'),
('H3 / título de lote','Fraunces 600 · 18/22','<span class="serif" style="font-size:18px;font-weight:600">A morte de Sócrates</span>'),
('Valor monetário','Fraunces 600 · 32 · tabular','<span class="price" style="font-size:32px">R$ 12.400,00</span>'),
('Corpo','Inter 400 · 14/20','<span>Lance mínimo para o próximo lance</span>'),
('Label / botão','Inter 600 · 13–15','<span style="font-weight:600">Dar lance</span>'),
('Legenda / crédito','Inter 400 · 12/16','<span class="small muted">The Met · CC0 · Domínio público</span>'),
('Cronômetro','Inter 600 · 28 · tabular-nums','<span class="num" style="font-size:28px;font-weight:600">01:58</span>')]
tyh=''.join(f'<tr><td style="width:200px"><b>{a}</b><div class="xs muted">{b}</div></td><td>{c}</td></tr>' for a,b,c in ty)
tok=[('Espaço','4 · 8 · 12 · 16 · 24 · 32 · 48 · 64 (base 4)'),('Grid desktop','12 col · 1360 útil · margem 40 · gutter 24'),('Grid mobile','4 col · margem 16 · gutter 12'),('Breakpoints','sm 640 · md 768 · lg 1024 · xl 1280'),('Alvo de toque','mín. 44×44 (Fitts); CTA primário 48'),('Foco','outline 2px --ring + offset 2px'),('Camadas','base 0 · sticky 10 · dropdown 20 · overlay 40 · dialog 50 · toast 60'),('Motion','120ms (hover) · 200ms (enter) · ease-out; reduced-motion: sem pulso/contagem animada')]
tokh=''.join(f'<tr><td style="width:160px"><b>{a}</b></td><td>{b}</td></tr>' for a,b in tok)
rad=''.join(f'<div style="text-align:center"><div style="width:72px;height:56px;background:var(--surface);border:1px solid var(--border);border-radius:{v}"></div><div class="xs" style="margin-top:6px"><b>{n}</b> {v}</div></div>' for n,v in [('sm','4px'),('md','6px'),('lg','10px'),('xl','14px'),('full','999px')])
sh=''.join(f'<div style="text-align:center"><div style="width:110px;height:64px;background:var(--surface);border-radius:10px;box-shadow:{v}"></div><div class="xs" style="margin-top:8px"><b>{n}</b><br>{u}</div></div>' for n,v,u in [('sm','var(--sh-sm)','cards, botões'),('md','var(--sh-md)','hover, popover'),('lg','var(--sh-lg)','dialog, toast')])
comp=[('Button','default(primary) · outline · ghost · destructive · sm/lg'),('Card','LoteCard, SaldoCard, ResumoLance'),('Badge','StatusLote, Integridade, Simulado, Origem'),('Tabs','Vitrine (ao vivo/agendados/encerrados)'),('Input + Label + Form','Valor do lance, depósito (prefixo R$)'),('Alert','Recusas, degradado, reconectando'),('AlertDialog','Confirmar lance, confirmar depósito'),('Dialog / Sheet','Depósito; menu mobile (Sheet)'),('Table','Histórico de lances, movimentações'),('Skeleton','Carregamento de cards e sala'),('Sonner (toast)','Lance aceito, depósito confirmado'),('Pagination','Vitrine, histórico'),('DropdownMenu + Avatar','Menu da conta (alias)'),('Tooltip','Explicação de comprometido'),('Separator · ScrollArea','Histórico com rolagem interna')]
comph=''.join(f'<tr><td style="width:200px"><b>{a}</b></td><td class="muted">{b}</td></tr>' for a,b in comp)
laws=[('Jakob','Padrões de e-commerce/leilão: cards com imagem, preço e CTA; cabeçalho com logo à esquerda e conta à direita.'),('Fitts','CTA “Dar lance” 48px, perto do valor; no mobile barra fixa inferior ao alcance do polegar.'),('Hick','Uma ação primária por tela; 3 abas na vitrine; atalhos de valor limitados a 3.'),('Miller','Carteira em 3 números; sala agrupa preço/prazo/posição em blocos de até 4 itens.'),('Postel','Campo aceita “1.500”, “1500,00” e “R$ 1500”; normaliza e mostra o valor interpretado.'),('Pico-fim','Pico: “Você está ganhando”/prorrogação; fim: arremate com comprovante e resumo claro.'),('Estética-usabilidade','Tipografia editorial + muito respiro passam confiança; nunca às custas de contraste (AA).')]
lawh=''.join(f'<tr><td style="width:170px"><b>{a}</b></td><td>{b}</td></tr>' for a,b in laws)
meta=f'''<div class="row" style="gap:24px;align-items:flex-start">
<div class="col" style="align-items:center;gap:6px"><div style="width:48px;height:48px">{logoA(48)}</div><span class="xs muted">favicon 32/16 (SVG + .ico)</span></div>
<div class="col" style="align-items:center;gap:6px">{logoA(96).replace('rx="6"','rx="0"')}<span class="xs muted">apple-touch-icon 180</span></div>
<div class="col" style="gap:6px"><div style="width:480px;height:252px;background:#6E1E2B;border-radius:8px;display:flex;overflow:hidden"><div style="flex:1;padding:28px;color:#FFF8F0;display:flex;flex-direction:column;justify-content:space-between"><div class="row">{logoA(36).replace('#6E1E2B','#5A1722')}<span class="serif" style="font-size:22px;font-weight:600">Arremate</span></div><div><div class="serif" style="font-size:26px;font-weight:600;line-height:1.15">Leilões de arte de acervo público</div><div style="font-size:13px;opacity:.85;margin-top:8px">Demonstração com valores simulados</div></div></div><div style="width:180px">{img('wheat','',252).replace('../assets/obras/436535.jpg','../assets/meta/og-art-436535.jpg')}</div></div><span class="xs muted">Open Graph 1200×630 (mostrado 40%) · alt: “Arremate — demonstração de leilões de arte de acervo público com valores simulados” · sem preço, prazo, saldo ou alias</span></div></div>'''
body=f'''<div class="board">{boardhead('Design system — proposta','Identidade, tokens e componentes sobre primitivas shadcn (tema via CSS variables). Somente tema claro (sem dark mode, decisão de 23/10). Valores são exemplos simulados.')}
<div class="sec"><h2>1 · Nome e logo — Arremate</h2><p class="d">Aprovado por Fernando em 23/10, segundo o Orquestrador Dev. Sem referência a Axion/Colinas; a Verzel não aparece como operadora.</p><div class="grid" style="grid-template-columns:1fr 2fr">{prop(logoA(48),'Arremate','“A” em Fraunces, moldura de latão sobre bordô. Termo do domínio (o momento de vencer = pico-fim).',True).replace('Recomendado','Aprovado')}<div class="card" style="padding:20px"><b class="small">Usos</b><div class="row" style="gap:28px;margin-top:12px">{logoA(64)}{logoA(32)}{logoA(16)}<div class="logo" style="font-size:26px">{logoA(36)}Arremate</div><div class="logo" style="font-size:26px;background:#6E1E2B;color:#FFF8F0;padding:8px 14px;border-radius:8px">{logoA(36).replace('#6E1E2B','#5A1722')}Arremate</div></div><p class="xs muted" style="margin-top:12px">Área de respiro = 1/4 do símbolo · mínimo 16px · não distorcer nem trocar cores.</p></div></div></div>
<div class="sec"><h2>2 · Paleta — “Bordô & Latão” (aprovada)</h2><p class="d">Papel quente, tinta escura, bordô de catálogo de leilão e latão como acento. Contraste medido: tinta/papel 15,4:1 · bordô/papel 10,1:1 · tinta-2/papel 6,7:1 · semânticas sobre fundo suave ≥ 5,6:1 · latão 3,2:1 (só foco e ornamento, nunca texto).</p>
<div class="grid" style="grid-template-columns:repeat(8,1fr);gap:12px">{pal}</div>
<h3 style="margin:20px 0 10px;font-size:15px">Semânticas (sempre com ícone + texto, nunca só cor)</h3><div class="grid" style="grid-template-columns:repeat(8,1fr);gap:12px">{sem}</div>
</div>
<div class="grid" style="grid-template-columns:1fr 1fr;margin-bottom:24px">
<div class="sec" style="margin:0"><h2>3 · Tipografia</h2><p class="d">Fraunces (títulos, valores) + Inter (UI). Ambas OFL. Números sempre tabulares.</p><table>{tyh}</table></div>
<div class="sec" style="margin:0"><h2>4 · Tokens</h2><p class="d">Mapeados para as variáveis shadcn (--background, --card, --primary, --ring, --radius…).</p><table>{tokh}</table>
<h3 style="margin:18px 0 10px;font-size:15px">Radius (--radius = 6px)</h3><div class="row" style="gap:16px">{rad}</div>
<h3 style="margin:18px 0 10px;font-size:15px">Sombras</h3><div class="row" style="gap:24px;padding:8px">{sh}</div></div></div>
<div class="sec"><h2>5 · Ícones — lucide (v1.61, ISC)</h2><p class="d">Traço 2px, 16px em texto, 20px em botões, 24px em destaques. Sempre com rótulo ou aria-label.</p><div class="grid" style="grid-template-columns:repeat(12,1fr);gap:8px">{ig}</div></div>
<div class="grid" style="grid-template-columns:1fr 1fr;margin-bottom:24px">
<div class="sec" style="margin:0"><h2>6 · Componentes (primitivas shadcn)</h2><p class="d">Sem biblioteca visual extra. Variantes na prancha 01.</p><table>{comph}</table></div>
<div class="sec" style="margin:0"><h2>7 · Leis de UX aplicadas</h2><p class="d">Onde cada lei pesa nas telas.</p><table>{lawh}</table>
<h3 style="margin:18px 0 8px;font-size:15px">Acessibilidade (meta WCAG 2.2 AA)</h3><p class="small">Foco visível em tudo; labels ligados a erros (aria-describedby); dialog com foco contido e retorno; lances anunciados em aria-live="polite" (não o cronômetro a cada segundo); zoom 200% sem perda; reduced-motion.</p></div></div>
<div class="sec"><h2>8 · Assets de metadados (U08)</h2><p class="d">Arquivos reais em assets/meta/ (favicon.svg, favicon.ico 32, apple-touch-icon.png 180, og-image.png 1200×630).</p>{meta}</div>
<div class="cred">Imagem OG: Vincent van Gogh, Wheat Field with Cypresses, 1889 — The Met, obj. 436535, Open Access CC0 (isPublicDomain=true, verificado na API em 23/10/2026).</div>
</div>'''
save('00-design-system',page('Design system',body,1440))
